import { mark, markViewBox, wordmark, wordmarkTagline, wordmarkTaglineViewBox, wordmarkViewBox } from "../assets/nexusBrand.generated";

/** The Nexus mark: a pixel-art N with a spark at its top right, drawn as SVG rects on its grid
 * (generated by scripts/brand_icons.py, see docs/brand/README.md), so it stays crisp at any size.
 *
 * Decorative by default (`aria-hidden`); give it a name with `alt="Nexus"` where it stands for
 * something on its own. Where it sits inside a button or link, the control keeps its own label.
 *
 * `variant` picks the colouring:
 * - `auto` (default) the full-colour mark; its Midnight pixels turn Blue/Teal on a dark theme, see the
 *   "Nexus mark" block at the end of styles.css. Use it on the page, cards and the chat.
 * - `mono` one colour, the text colour around it: on an accent-coloured button the button's own
 *   `--on-accent`, so it reads in both themes.
 * - `cloud` all Cloud, for a dark or saturated fill that stays that way in both themes.
 * - `ink` all Midnight, for a light or Lime fill. */
export type NexusMarkVariant = "auto" | "mono" | "cloud" | "ink";

const CLOUD = "#F8FAFC";
const INK = "#0B1020";
// Fixed colours of the full-colour mark; K, k and b are the pixels that change with the theme.
const FILL: Record<string, string> = { B: "#2563EB", b: "#2563EB", T: "#22D3EE", L: "#A3FF12", K: INK, k: INK };

const [VX, VY, VW, VH] = markViewBox;

export function NexusMark({
  size = 32,
  big = false,
  alt = "",
  className,
  variant = "auto",
}: {
  /** Width in px. The mark sits centred in a square box this wide, so it can stand in for any square slot. */
  size?: number;
  /** The hero size: the box is as tall as the mark itself rather than square. */
  big?: boolean;
  alt?: string;
  className?: string;
  variant?: NexusMarkVariant;
}) {
  const classes = `nexus-mark${big ? " nexus-mark-big" : ""}${className ? ` ${className}` : ""}`;
  const height = big ? Math.round((size * VH) / VW) : size;
  return (
    <svg
      className={classes}
      viewBox={`${VX} ${VY} ${VW} ${VH}`}
      width={size}
      height={height}
      shapeRendering="crispEdges"
      preserveAspectRatio="xMidYMid meet"
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={alt ? undefined : true}
      focusable="false"
    >
      {mark.map(([x, y, w, h, key], i) => (
        <rect
          key={i}
          x={x}
          y={y}
          width={w}
          height={h}
          fill={variant === "mono" ? "currentColor" : variant === "cloud" ? CLOUD : variant === "ink" ? INK : FILL[key]}
          className={variant === "auto" && (key === "K" || key === "k" || key === "b") ? `nm-${key}` : undefined}
        />
      ))}
    </svg>
  );
}

/** NEXUS in blocky pixel capitals (one colour: the text colour around it), with the optional
 * AI LIFESTYLE MANAGER line under it. Decorative unless given an `alt`. */
export function NexusWordmark({
  height = 24,
  tagline = false,
  alt = "",
  className,
}: {
  /** Height in px of the whole block (the letters alone, or letters and tagline). */
  height?: number;
  tagline?: boolean;
  alt?: string;
  className?: string;
}) {
  const [, , vw, vh] = tagline ? wordmarkTaglineViewBox : wordmarkViewBox;
  const rects = tagline ? wordmarkTagline : wordmark;
  return (
    <svg
      className={`nexus-wordmark${className ? ` ${className}` : ""}`}
      viewBox={`0 0 ${vw} ${vh}`}
      width={Math.round((height * vw) / vh)}
      height={height}
      shapeRendering="crispEdges"
      fill="currentColor"
      role={alt ? "img" : undefined}
      aria-label={alt || undefined}
      aria-hidden={alt ? undefined : true}
      focusable="false"
    >
      {rects.map(([x, y, w, h], i) => (
        <rect key={i} x={x} y={y} width={w} height={h} />
      ))}
    </svg>
  );
}
